def cholesky_decomposition(matrix: List[List[float]]) -> List[List[float]]:
    try:
        ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
        matrix_ptr = gsl.gsl_matrix_alloc(len(matrix), len(matrix))
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                matrix_ptr[i, j] = matrix[i][j]
        if not gsl.gsl_linalg_cholesky_is_positive_definite(matrix_ptr):
            raise ValueError('Matrix is not positive definite')
        L = (ctypes.c_float * len(matrix) * len(matrix))() 
        gsl.gsl_linalg_cholesky_decomp(matrix_ptr, L)
        result = [[L[i * len(matrix) + j] for j in range(len(matrix))] for i in range(len(matrix))]
        return result
    except Exception as e:
        print(f'Error: {e}')
        return []

